1	import { notFound } from "next/navigation";
2	import { createClient } from "@/lib/supabase/server";
3	import { addKitchenPrinter, addPaymentMethod, updateBusinessType, updateTaxService } from "./actions";
4	import AddPaymentMethodForm from "./add-payment-method-form";
5	import AddPrinterForm from "./add-printer-form";
6	import BusinessTypeForm from "./business-type-form";
7	import DeletePaymentMethodButton from "./delete-payment-method-button";
8	import DeletePrinterButton from "./delete-printer-button";
9	import TaxServiceForm from "./tax-service-form";
10	import TicketCategoriesSection from "./ticket-categories-section";
11	import TicketHolidaysSection from "./ticket-holidays-section";
12	
13	export default async function SettingsPage({
14	  params,
15	}: {
16	  params: Promise<{ businessId: string }>;
17	}) {
18	  const { businessId } = await params;
19	  const supabase = await createClient();
20	
21	  const { data: business } = await supabase
22	    .from("businesses")
23	    .select("id, name, business_type, tax_enabled, tax_rate, service_enabled, service_rate")
24	    .eq("id", businessId)
25	    .single();
26	
27	  if (!business) {
28	    notFound();
29	  }
30	
31	  const isFnb = business.business_type === "fnb";
32	  const isTiket = business.business_type === "tiket";
33	
34	  let ticketCategories: {
35	    id: string;
36	    name: string;
37	    price_weekday: number;
38	    price_holiday: number;
39	    member_price: number;
40	    group_min_qty: number;
41	    group_price: number | null;
42	  }[] = [];
43	  let ticketHolidays: { id: string; holiday_date: string; label: string | null }[] = [];
44	
45	  if (isTiket) {
46	    const { data: categoryRows } = await supabase
47	      .from("ticket_categories")
48	      .select(
49	        "id, name, price_weekday, price_holiday, member_price, group_min_qty, group_price",
50	      )
51	      .eq("business_id", businessId)
52	      .is("deleted_at", null)
53	      .order("name", { ascending: true });
54	    ticketCategories = (categoryRows ?? []).map((c) => ({
55	      ...c,
56	      price_weekday: Number(c.price_weekday),
57	      price_holiday: Number(c.price_holiday),
58	      member_price: Number(c.member_price),
59	      group_min_qty: Number(c.group_min_qty),
60	      group_price: c.group_price == null ? null : Number(c.group_price),
61	    }));
62	
63	    const { data: holidayRows } = await supabase
64	      .from("ticket_holidays")
65	      .select("id, holiday_date, label")
66	      .eq("business_id", businessId)
67	      .order("holiday_date", { ascending: true });
68	    ticketHolidays = holidayRows ?? [];
69	  }
70	
71	  const { data: paymentMethods } = await supabase
72	    .from("custom_payment_methods")
73	    .select("id, name")
74	    .eq("business_id", businessId)
75	    .order("name", { ascending: true });
76	
77	  const [{ data: txRows }, { data: ticketTxRows }] = await Promise.all([
78	    supabase.from("transactions").select("id").eq("business_id", businessId).limit(1),
79	    supabase.from("ticket_transactions").select("id").eq("business_id", businessId).limit(1),
80	  ]);
81	  const hasTransactions = (txRows && txRows.length > 0) || (ticketTxRows && ticketTxRows.length > 0);
82	
83	  const boundAddPaymentMethod = addPaymentMethod.bind(null, businessId);
84	  const boundUpdateBusinessType = updateBusinessType.bind(null, businessId);
85	
86	  let printers: {
87	    id: string;
88	    name: string;
89	    categories: string[];
90	    connection_type: string;
91	    address: string | null;
92	    device_label: string | null;
93	  }[] = [];
94	  let productCategories: string[] = [];
95	
96	  if (isFnb) {
97	    const { data: printerRows } = await supabase
98	      .from("kitchen_printers")
99	      .select("id, name, categories, connection_type, address, device_label")
100	      .eq("business_id", businessId)
101	      .order("name", { ascending: true });
102	    printers = printerRows ?? [];
103	
104	    const { data: categoryRows } = await supabase
105	      .from("products")
106	      .select("category")
107	      .eq("business_id", businessId)
108	      .is("deleted_at", null)
109	      .not("category", "is", null);
110	    productCategories = Array.from(
111	      new Set((categoryRows ?? []).map((r) => r.category as string).filter(Boolean)),
112	    ).sort();
113	  }
114	
115	  const boundAddKitchenPrinter = addKitchenPrinter.bind(null, businessId);
116	
117	  return (
118	    <div className="w-full max-w-2xl">
119	        <h1 className="text-lg font-bold text-zinc-900">Pengaturan — {business.name}</h1>
120	
121	        {/* Jenis Usaha */}
122	        <div className="mt-6 rounded-xl bg-white shadow-sm p-5">
123	          <h2 className="text-sm font-semibold text-zinc-900">Jenis Usaha</h2>
124	          <p className="mt-1 text-xs text-zinc-500">
125	            Menentukan menu &amp; alur kasir yang muncul (F&amp;B, Retail, atau Tempat
126	            Wisata/Tiket).
127	          </p>
128	          <div className="mt-4">
129	            {hasTransactions ? (
130	              <p className="rounded-xl border border-dashed border-zinc-200 px-4 py-4 text-xs text-zinc-500">
131	                🔒 Toko ini sudah punya transaksi, jadi jenis usaha tidak bisa diganti lagi.
132	                Hubungi kami kalau butuh bantuan.
133	              </p>
134	            ) : (
135	              <BusinessTypeForm
136	                action={boundUpdateBusinessType}
137	                businessType={business.business_type}
138	              />
139	            )}
140	          </div>
141	        </div>
142	
143	        {/* Pajak & Biaya Layanan */}
144	        <div className="mt-6 rounded-xl bg-white shadow-sm p-5">
145	          <h2 className="text-sm font-semibold text-zinc-900">Pajak &amp; Biaya Layanan</h2>
146	          <p className="mt-1 text-xs text-zinc-500">
147	            Ditambahkan otomatis ke setiap transaksi di kasir.
148	          </p>
149	          <div className="mt-4">
150	            <TaxServiceForm
151	              action={updateTaxService.bind(null, businessId)}
152	              taxEnabled={business.tax_enabled}
153	              taxRate={Number(business.tax_rate)}
154	              serviceEnabled={business.service_enabled}
155	              serviceRate={Number(business.service_rate)}
156	            />
157	          </div>
158	        </div>
159	
160	        {/* Metode Pembayaran Custom */}
161	        <div className="mt-6 rounded-xl bg-white shadow-sm p-5">
162	          <h2 className="text-sm font-semibold text-zinc-900">Metode Pembayaran Custom</h2>
163	          <p className="mt-1 text-xs text-zinc-500">
164	            Tambahan di luar Tunai, Kartu, QRIS — misalnya dompet digital atau transfer bank
165	            tertentu.
166	          </p>
167	
168	          <div className="mt-4 space-y-2">
169	            {paymentMethods && paymentMethods.length > 0 ? (
170	              paymentMethods.map((m) => (
171	                <div
172	                  key={m.id}
173	                  className="flex items-center justify-between rounded-xl border border-zinc-200 bg-white px-4 py-2.5"
174	                >
175	                  <p className="text-sm font-medium text-zinc-900">{m.name}</p>
176	                  <DeletePaymentMethodButton businessId={businessId} methodId={m.id} />
177	                </div>
178	              ))
179	            ) : (
180	              <p className="rounded-xl border border-dashed border-zinc-200 px-4 py-4 text-center text-xs text-zinc-400">
181	                Belum ada metode pembayaran custom.
182	              </p>
183	            )}
184	          </div>
185	
186	          <div className="mt-4">
187	            <AddPaymentMethodForm action={boundAddPaymentMethod} />
188	          </div>
189	        </div>
190	
191	        {/* Printer Dapur & Bar (F&B only) */}
192	        {isFnb && (
193	          <div className="mt-6 rounded-xl bg-white shadow-sm p-5">
194	            <h2 className="text-sm font-semibold text-zinc-900">Printer Dapur &amp; Bar</h2>
195	            <p className="mt-1 text-xs text-zinc-500">
196	              Cetak order otomatis ke printer dapur/bar sesuai kategori menu — bukan ke kasir.
197	            </p>
198	
199	            <div className="mt-4 space-y-2">
200	              {printers.length > 0 ? (
201	                printers.map((p) => (
202	                  <div key={p.id} className="rounded-xl border border-zinc-200 bg-white px-4 py-3">
203	                    <div className="flex items-center justify-between">
204	                      <p className="text-sm font-medium text-zinc-900">{p.name}</p>
205	                      <DeletePrinterButton businessId={businessId} printerId={p.id} />
206	                    </div>
207	                    <p className="mt-0.5 text-xs text-zinc-500">
208	                      {p.connection_type === "lan" ? "🌐 LAN/Wi-Fi" : "📶 Bluetooth"}
209	                      {p.address
210	                        ? ` · ${p.connection_type === "bluetooth" ? (p.device_label ?? p.address) : p.address}`
211	                        : ""}
212	                    </p>
213	                    {p.categories.length > 0 && (
214	                      <p className="mt-1 text-[11px] text-zinc-400">
215	                        Kategori: {p.categories.join(", ")}
216	                      </p>
217	                    )}
218	                  </div>
219	                ))
220	              ) : (
221	                <p className="rounded-xl border border-dashed border-zinc-200 px-4 py-4 text-center text-xs text-zinc-400">
222	                  Belum ada printer dapur/bar. Order akan tetap dicetak di kasir saja.
223	                </p>
224	              )}
225	            </div>
226	
227	            <div className="mt-4 border-t border-zinc-100 pt-4">
228	              <AddPrinterForm action={boundAddKitchenPrinter} categories={productCategories} />
229	            </div>
230	          </div>
231	        )}
232	
233	        {/* Kategori & Harga Tiket + Kalender Libur (tiket only) */}
234	        {isTiket && (
235	          <>
236	            <TicketCategoriesSection businessId={businessId} categories={ticketCategories} />
237	            <TicketHolidaysSection businessId={businessId} holidays={ticketHolidays} />
238	          </>
239	        )}
240	    </div>
241	  );
242	}
