1	"use client";
2	
3	import { useEffect, useMemo, useState, type KeyboardEvent } from "react";
4	import { useRouter } from "next/navigation";
5	import Link from "next/link";
6	import {
7	  addShiftCashMovement,
8	  checkout,
9	  closeShift,
10	  deleteOpenBill,
11	  saveOpenBill,
12	  updateSelfOrderStatus,
13	  type CheckoutResult,
14	  type CloseShiftSummary,
15	  type DiscountType,
16	} from "./actions";
17	import SwitchCashierButton from "./switch-cashier-button";
18	import OfflineStatus from "./offline-status";
19	import { itemDiscAmount, calculateCheckoutTotals } from "@/lib/checkout-totals";
20	import { useOfflineSync } from "@/hooks/use-offline-sync";
21	import { enqueueSale, pendingStockDeltas } from "@/lib/offline-queue";
22	import { withTimeout } from "@/lib/with-timeout";
23	import { dispatchPrintJobs } from "@/lib/dispatch-print-jobs";
24	
25	type Product = {
26	  id: string;
27	  name: string;
28	  category: string | null;
29	  price: number;
30	  cost: number;
31	  stock: number;
32	  emoji: string | null;
33	  barcode: string | null;
34	  sku: string | null;
35	  variant_label: string | null;
36	};
37	
38	type CartItem = {
39	  productId: string;
40	  name: string;
41	  price: number;
42	  qty: number;
43	  maxStock: number;
44	  disc: number;
45	  discType: DiscountType;
46	};
47	
48	type SelfOrder = {
49	  id: string;
50	  status: "baru" | "diproses";
51	  createdAt: string;
52	  tableName: string;
53	  items: {
54	    productId: string | null;
55	    name: string;
56	    qty: number;
57	    price: number;
58	    note: string | null;
59	  }[];
60	};
61	
62	type OpenBill = {
63	  id: string;
64	  label: string;
65	  updated_at: string;
66	  items: {
67	    product_id: string;
68	    name: string;
69	    price: number;
70	    qty: number;
71	    disc: number;
72	    disc_type: DiscountType;
73	  }[];
74	};
75	
76	type Customer = {
77	  id: string;
78	  name: string;
79	  phone: string | null;
80	};
81	
82	const BUILTIN_PAYMENT_METHODS = ["Tunai", "Kartu", "QRIS"];
83	
84	function formatRupiah(value: number) {
85	  return `Rp${value.toLocaleString("id-ID")}`;
86	}
87	
88	export default function PosScreen({
89	  businessId,
90	  businessName,
91	  cashierId,
92	  cashierName,
93	  shiftId,
94	  products,
95	  taxRate,
96	  serviceRate,
97	  openBills,
98	  customers,
99	  isFnb,
100	  selfOrders,
101	  customPaymentMethods,
102	}: {
103	  businessId: string;
104	  businessName: string;
105	  cashierId: string;
106	  cashierName: string;
107	  shiftId: string;
108	  products: Product[];
109	  taxRate: number;
110	  serviceRate: number;
111	  openBills: OpenBill[];
112	  customers: Customer[];
113	  isFnb: boolean;
114	  selfOrders: SelfOrder[];
115	  customPaymentMethods: string[];
116	}) {
117	  const router = useRouter();
118	  const paymentMethods = useMemo(
119	    () => [...BUILTIN_PAYMENT_METHODS, ...customPaymentMethods],
120	    [customPaymentMethods],
121	  );
122	  const [search, setSearch] = useState("");
123	  const [scanFeedback, setScanFeedback] = useState<string | null>(null);
124	  const [cart, setCart] = useState<CartItem[]>([]);
125	  const [cartOrderIds, setCartOrderIds] = useState<string[]>([]);
126	  const [inboxOpen, setInboxOpen] = useState(false);
127	  const [inboxNotice, setInboxNotice] = useState<string | null>(null);
128	  const [orderBusyId, setOrderBusyId] = useState<string | null>(null);
129	  const [editingDiscId, setEditingDiscId] = useState<string | null>(null);
130	  const [orderDisc, setOrderDisc] = useState(0);
131	  const [orderDiscType, setOrderDiscType] = useState<DiscountType>("pct");
132	  const [orderDiscOpen, setOrderDiscOpen] = useState(false);
133	  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
134	  const [customerPickerOpen, setCustomerPickerOpen] = useState(false);
135	  const [customerSearch, setCustomerSearch] = useState("");
136	  const [billsOpen, setBillsOpen] = useState(false);
137	  const [posMenuOpen, setPosMenuOpen] = useState(false);
138	  const [billBusyId, setBillBusyId] = useState<string | null>(null);
139	  const [activeBill, setActiveBill] = useState<{ id: string; label: string } | null>(null);
140	  const [saveBonOpen, setSaveBonOpen] = useState(false);
141	  const [bonLabel, setBonLabel] = useState("");
142	  const [bonError, setBonError] = useState<string | null>(null);
143	  const [bonSaving, setBonSaving] = useState(false);
144	
145	  const newOrderCount = selfOrders.filter((o) => o.status === "baru").length;
146	
147	  // Order self-order masuk dari perangkat pelanggan; poll supaya badge kasir
148	  // ikut terbarui tanpa reload manual. router.refresh() mempertahankan state
149	  // client (keranjang tidak hilang).
150	  useEffect(() => {
151	    if (!isFnb) return;
152	    const interval = setInterval(() => router.refresh(), 15000);
153	    return () => clearInterval(interval);
154	  }, [isFnb, router]);
155	  const [paying, setPaying] = useState(false);
156	  const [paymentMethod, setPaymentMethod] = useState(BUILTIN_PAYMENT_METHODS[0]);
157	  const [received, setReceived] = useState("");
158	  const [submitting, setSubmitting] = useState(false);
159	  const [error, setError] = useState<string | null>(null);
160	  const [successInvoice, setSuccessInvoice] = useState<string | null>(null);
161	  const [successTransactionId, setSuccessTransactionId] = useState<string | null>(null);
162	  const [successOffline, setSuccessOffline] = useState(false);
163	
164	  const { isOnline, pending, syncNow, discard } = useOfflineSync(businessId);
165	  const effectiveProducts = useMemo(() => {
166	    const deltas = pendingStockDeltas(pending);
167	    if (Object.keys(deltas).length === 0) return products;
168	    return products.map((p) =>
169	      deltas[p.id] ? { ...p, stock: Math.max(0, p.stock - deltas[p.id]) } : p,
170	    );
171	  }, [products, pending]);
172	
173	  const [closingShift, setClosingShift] = useState(false);
174	  const [closingCash, setClosingCash] = useState("");
175	  const [closeNotes, setCloseNotes] = useState("");
176	  const [closeError, setCloseError] = useState<string | null>(null);
177	  const [closeSubmitting, setCloseSubmitting] = useState(false);
178	  const [closedSummary, setClosedSummary] = useState<CloseShiftSummary | null>(null);
179	
180	  const [cashMoveOpen, setCashMoveOpen] = useState(false);
181	  const [cashMoveDirection, setCashMoveDirection] = useState<"in" | "out">("out");
182	  const [cashMoveAmount, setCashMoveAmount] = useState("");
183	  const [cashMoveDesc, setCashMoveDesc] = useState("");
184	  const [cashMoveError, setCashMoveError] = useState<string | null>(null);
185	  const [cashMoveSubmitting, setCashMoveSubmitting] = useState(false);
186	
187	  const filteredProducts = useMemo(() => {
188	    const q = search.trim().toLowerCase();
189	    if (!q) return effectiveProducts;
190	    return effectiveProducts.filter(
191	      (p) =>
192	        p.name.toLowerCase().includes(q) ||
193	        p.barcode?.toLowerCase() === q ||
194	        p.sku?.toLowerCase() === q,
195	    );
196	  }, [search, effectiveProducts]);
197	
198	  // Variants are just extra product rows sharing the same name — group them
199	  // here purely for display, no schema relationship involved.
200	  const productGroups = useMemo(() => {
201	    const groups: { name: string; variants: Product[] }[] = [];
202	    for (const p of filteredProducts) {
203	      const existing = groups.find((g) => g.name === p.name);
204	      if (existing) {
205	        existing.variants.push(p);
206	      } else {
207	        groups.push({ name: p.name, variants: [p] });
208	      }
209	    }
210	    return groups;
211	  }, [filteredProducts]);
212	
213	  const [variantPickerGroup, setVariantPickerGroup] = useState<{
214	    name: string;
215	    variants: Product[];
216	  } | null>(null);
217	
218	  function handleProductClick(group: { name: string; variants: Product[] }) {
219	    if (group.variants.length === 1) {
220	      addToCart(group.variants[0]);
221	    } else {
222	      setVariantPickerGroup(group);
223	    }
224	  }
225	
226	  // Barcode scanners act like a keyboard: they type the code then send
227	  // Enter. On Enter, an exact barcode/SKU match jumps straight into the cart
228	  // instead of just filtering the grid.
229	  useEffect(() => {
230	    if (!scanFeedback) return;
231	    const timer = setTimeout(() => setScanFeedback(null), 2500);
232	    return () => clearTimeout(timer);
233	  }, [scanFeedback]);
234	
235	  function handleSearchKeyDown(e: KeyboardEvent<HTMLInputElement>) {
236	    if (e.key !== "Enter") return;
237	    const q = search.trim();
238	    if (!q) return;
239	    const match = effectiveProducts.find((p) => p.barcode === q || p.sku === q);
240	    if (match) {
241	      addToCart(match);
242	      setSearch("");
243	      setScanFeedback(null);
244	    } else if (effectiveProducts.some((p) => p.barcode || p.sku)) {
245	      setScanFeedback(`"${q}" tidak ditemukan.`);
246	    }
247	  }
248	
249	  const filteredCustomers = useMemo(() => {
250	    const q = customerSearch.trim().toLowerCase();
251	    if (!q) return customers;
252	    return customers.filter(
253	      (c) => c.name.toLowerCase().includes(q) || c.phone?.toLowerCase().includes(q),
254	    );
255	  }, [customerSearch, customers]);
256	
257	  const { subtotalRaw, totalItemDisc, afterItemDisc, orderDiscAmt, serviceAmt, taxAmt, total } =
258	    calculateCheckoutTotals({
259	      items: cart,
260	      orderDisc,
261	      orderDiscType,
262	      serviceRate,
263	      taxRate,
264	    });
265	  const receivedAmount = Number(received) || 0;
266	  const change = paymentMethod === "Tunai" ? receivedAmount - total : 0;
267	
268	  function addToCart(product: Product) {
269	    setCart((prev) => {
270	      const existing = prev.find((i) => i.productId === product.id);
271	      if (existing) {
272	        if (existing.qty >= product.stock) return prev;
273	        return prev.map((i) =>
274	          i.productId === product.id ? { ...i, qty: i.qty + 1 } : i,
275	        );
276	      }
277	      if (product.stock <= 0) return prev;
278	      return [
279	        ...prev,
280	        {
281	          productId: product.id,
282	          name: product.variant_label ? `${product.name} (${product.variant_label})` : product.name,
283	          price: product.price,
284	          qty: 1,
285	          maxStock: product.stock,
286	          disc: 0,
287	          discType: "pct" as DiscountType,
288	        },
289	      ];
290	    });
291	  }
292	
293	  function setItemDisc(productId: string, disc: number, discType: DiscountType) {
294	    setCart((prev) =>
295	      prev.map((i) => (i.productId === productId ? { ...i, disc, discType } : i)),
296	    );
297	  }
298	
299	  function changeQty(productId: string, delta: number) {
300	    setCart((prev) =>
301	      prev
302	        .map((i) =>
303	          i.productId === productId
304	            ? { ...i, qty: Math.min(i.maxStock, Math.max(0, i.qty + delta)) }
305	            : i,
306	        )
307	        .filter((i) => i.qty > 0),
308	    );
309	  }
310	
311	  function removeFromCart(productId: string) {
312	    setCart((prev) => prev.filter((i) => i.productId !== productId));
313	  }
314	
315	  async function handleSaveBon() {
316	    setBonError(null);
317	    setBonSaving(true);
318	    const result = await saveOpenBill(
319	      businessId,
320	      activeBill?.id ?? null,
321	      bonLabel,
322	      cart.map((i) => ({
323	        product_id: i.productId,
324	        name: i.name,
325	        price: i.price,
326	        qty: i.qty,
327	        disc: i.disc,
328	        disc_type: i.discType,
329	      })),
330	    );
331	    setBonSaving(false);
332	
333	    if (!result.success) {
334	      setBonError(result.error);
335	      return;
336	    }
337	
338	    setCart([]);
339	    setCartOrderIds([]);
340	    setOrderDisc(0);
341	    setOrderDiscType("pct");
342	    setActiveBill(null);
343	    setSaveBonOpen(false);
344	    setBonLabel("");
345	    router.refresh();
346	  }
347	
348	  function handleLoadBill(bill: OpenBill) {
349	    if (
350	      cart.length > 0 &&
