1	import type { SupabaseClient } from "@supabase/supabase-js";
2	import { buildKitchenTicket, type KitchenTicketItem } from "./escpos";
3	
4	export type KitchenPrintJob = {
5	  source: string;
6	  label: string;
7	  items: (KitchenTicketItem & { category: string | null })[];
8	};
9	
10	// Ticket-building stays server-side (uses Buffer, reads kitchen_printers via
11	// the caller's Supabase client) — only the actual byte-sending moves to the
12	// client, since Vercel can never reach a printer's private LAN IP or a
13	// Bluetooth device, but the cashier's browser/app (physically on the shop's
14	// network, or physically holding the tablet) can. connectionType tells the
15	// client which transport to use: print-agent/native-LAN for "lan", the
16	// native Bluetooth plugin for "bluetooth" (browsers without the plugin can't
17	// do anything with a bluetooth job — see dispatch-print-jobs.ts).
18	export type KitchenPrintJobPayload = {
19	  printerName: string;
20	  address: string;
21	  connectionType: "lan" | "bluetooth";
22	  bytesBase64: string;
23	};
24	
25	export async function buildKitchenPrintJobs(
26	  supabase: SupabaseClient,
27	  businessId: string,
28	  job: KitchenPrintJob,
29	): Promise<KitchenPrintJobPayload[]> {
30	  if (job.items.length === 0) return [];
31	
32	  const { data: printers } = await supabase
33	    .from("kitchen_printers")
34	    .select("id, name, categories, connection_type, address")
35	    .eq("business_id", businessId);
36	
37	  const addressedPrinters = (printers ?? []).filter((p) => !!p.address) as {
38	    id: string;
39	    name: string;
40	    categories: string[];
41	    connection_type: "lan" | "bluetooth";
42	    address: string;
43	  }[];
44	
45	  const attempts = addressedPrinters
46	    .map((printer) => {
47	      const items =
48	        printer.categories.length > 0
49	          ? job.items.filter((i) => i.category && printer.categories.includes(i.category))
50	          : job.items;
51	      return { printer, items };
52	    })
53	    .filter((a) => a.items.length > 0);
54	
55	  return attempts.map(({ printer, items }) => {
56	    const buffer = buildKitchenTicket({
57	      station: printer.name,
58	      source: job.source,
59	      label: job.label,
60	      items,
61	    });
62	    return {
63	      printerName: printer.name,
64	      address: printer.address,
65	      connectionType: printer.connection_type,
66	      bytesBase64: buffer.toString("base64"),
67	    };
68	  });
69	}
