1	"use client";
2	
3	import { Capacitor } from "@capacitor/core";
4	import { printViaAgent, type PrintAgentResult } from "./print-agent-client";
5	import KitchenPrinter from "./kitchen-printer-plugin";
6	import type { KitchenPrintJobPayload } from "./kitchen-print";
7	import { logKitchenPrintFailures } from "@/app/business/[businessId]/pos/actions";
8	
9	// Android app (android-app/) supplies KitchenPrinter natively — the browser
10	// on the cashier's own tablet is on the shop's LAN (or physically holding
11	// it, for Bluetooth), so it can dial the printer directly, no print-agent PC
12	// needed. Plain browsers keep using the print-agent HTTP relay for LAN jobs
13	// (untouched); they have no way to reach a bluetooth job at all.
14	async function dispatchOne(job: KitchenPrintJobPayload): Promise<PrintAgentResult> {
15	  if (Capacitor.isNativePlatform()) {
16	    const result =
17	      job.connectionType === "lan"
18	        ? await (() => {
19	            const [ip, portStr] = job.address.split(":");
20	            const port = portStr ? Number(portStr) : 9100;
21	            return KitchenPrinter.printLan({ ip, port, bytesBase64: job.bytesBase64 });
22	          })()
23	        : await KitchenPrinter.printBluetooth({ address: job.address, bytesBase64: job.bytesBase64 });
24	    return result.ok
25	      ? { ok: true }
26	      : { ok: false, reason: "printer_unreachable", error: result.error ?? "unknown_error" };
27	  }
28	  if (job.connectionType === "bluetooth") {
29	    return { ok: false, reason: "printer_unreachable", error: "unsupported_on_web" };
30	  }
31	  return printViaAgent(job.address, job.bytesBase64);
32	}
33	
34	// Fire-and-forget from the caller's point of view — a failed kitchen print
35	// must never block or fail the sale/order that triggered it (same principle
36	// the old server-side dispatchKitchenPrint followed).
37	export async function dispatchPrintJobs(businessId: string, jobs: KitchenPrintJobPayload[]) {
38	  if (jobs.length === 0) return;
39	
40	  const results = await Promise.all(
41	    jobs.map(async (job) => ({ job, result: await dispatchOne(job) })),
42	  );
43	
44	  const failed = results.filter((r) => !r.result.ok);
45	  if (failed.length > 0) {
46	    await logKitchenPrintFailures(
47	      businessId,
48	      failed.map(({ job, result }) => ({
49	        printer: job.printerName,
50	        error: result.ok ? "" : result.error,
51	      })),
52	    ).catch(() => {});
53	  }
54	}
