5	import CheckInScreen from "./check-in-screen";
6	
7	export default async function CheckInPage({
8	  params,
9	}: {
10	  params: Promise<{ businessId: string }>;
11	}) {
12	  const { businessId } = await params;
13	  const supabase = await createClient();
14	
15	  const { data: business } = await supabase
16	    .from("businesses")
17	    .select("id, name")
18	    .eq("id", businessId)
19	    .single();
20	
21	  if (!business) {
22	    notFound();
23	  }
24	
25	  const session = await getCashierSession(businessId);
26	
27	  if (!session) {
28	    const { data: cashiers } = await supabase
29	      .from("cashiers")
30	      .select("id, name, role")
31	      .eq("business_id", businessId)
32	      .eq("active", true)
33	      .order("created_at", { ascending: true });
34	
35	    return (
36	      <PinScreen
37	        businessId={businessId}
38	        businessName={business.name}
39	        cashiers={cashiers ?? []}
40	      />
41	    );
42	  }
43	
44	  const { data: categoryRows } = await supabase
45	    .from("ticket_categories")
46	    .select("id, name")
47	    .eq("business_id", businessId)
48	    .eq("active", true)
49	    .is("deleted_at", null)
50	    .order("name", { ascending: true });
51	
52	  return (
53	    <CheckInScreen
54	      businessId={businessId}
55	      businessName={business.name}
56	      cashierId={session.cashierId}
57	      cashierName={session.name}
58	      categories={categoryRows ?? []}
59	    />
60	  );
61	}
